import {scrollProgress,clamp} from './gallery-math.js';
export function galleryMarkup(works){const w=works[0];return `<section class="gallery-story" style="--stops:${works.length}" aria-label="Galerie photographique immersive"><div class="gallery-pin"><div class="gallery-intro"><p>Photographie documentaire</p><a href="#series">Explorer toutes les séries</a></div><div class="gallery-view"><p class="gallery-instruction">Défilez pour parcourir l’accrochage<span aria-hidden="true"></span></p></div><div class="gallery-cartel"><div class="gallery-label"><p id="gallery-place">${w.place} · ${w.period}</p><h1 id="gallery-work-title">${w.title}</h1><p id="gallery-subtitle">${w.subtitle}</p></div><a class="gallery-detail" href="#serie/${w.project}">Voir la série</a><div class="gallery-pagination"><button type="button" class="gallery-previous" aria-label="Photographie précédente" disabled><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg></button><span class="gallery-count" aria-live="polite">01 / ${String(works.length).padStart(2,'0')}</span><button type="button" class="gallery-next" aria-label="Photographie suivante"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m10 6 6 6-6 6"/></svg></button></div></div><div class="gallery-track" aria-hidden="true"><span></span></div><div class="gallery-credit"><span>Photographies © Antoine Martin</span><a href="#a-propos">Le photographe</a></div></div></section>`;}
export function mountGallery(section,works,{initialProgress=0,onPosition,world}){
 const $=selector=>section.querySelector(selector);let index=-1,frame=0,disposed=false;
 const dimensions=()=>({top:section.getBoundingClientRect().top+scrollY,travel:Math.max(0,section.offsetHeight-$('.gallery-pin').offsetHeight)});
 function caption(state){$('.gallery-track span').style.transform=`scaleX(${state.progress/(works.length-1)})`;if(index===state.index)return;index=state.index;const w=works[index];$('#gallery-work-title').textContent=w.title;$('#gallery-place').textContent=`${w.place} · ${w.period}`;$('#gallery-subtitle').textContent=w.subtitle;$('.gallery-detail').href=`#serie/${w.project}`;$('.gallery-count').textContent=`${String(index+1).padStart(2,'0')} / ${String(works.length).padStart(2,'0')}`;$('.gallery-previous').disabled=index===0;$('.gallery-next').disabled=index===works.length-1;}
 function update(){frame=0;if(disposed)return;const {top,travel}=dimensions();world.visit(scrollProgress(scrollY,top,travel,works.length),caption);}
 function schedule(){if(!frame)frame=requestAnimationFrame(update);}
 function goTo(point){const {top,travel}=dimensions();window.scrollTo({top:top+clamp(point,0,works.length-1)/(works.length-1)*travel,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
 $('.gallery-previous').addEventListener('click',()=>goTo(index-1));$('.gallery-next').addEventListener('click',()=>goTo(index+1));
 section.addEventListener('keydown',event=>{if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();goTo(index+(event.key==='ArrowRight'?1:-1));}});
 const observer=new ResizeObserver(()=>{world.layout();schedule();});observer.observe($('.gallery-cartel'));window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);world.visit(initialProgress,caption);requestAnimationFrame(()=>{if(disposed)return;const {top,travel}=dimensions();window.scrollTo({top:top+initialProgress/(works.length-1)*travel,behavior:'instant'});schedule();});
 return ()=>{onPosition(world.position());disposed=true;world.stopVisit();cancelAnimationFrame(frame);observer.disconnect();window.removeEventListener('scroll',schedule);window.removeEventListener('resize',schedule);};
}
